import Foundation

// macOS: swiftc Sources/CapturePolicy.swift Tests/CapturePolicyTests.swift -o /tmp/CapturePolicyTests && /tmp/CapturePolicyTests
@main
enum CapturePolicyTests {
    // Independent expectation: do not derive test cases from the production marker list.
    static let markers = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
    ]

    static func main() {
        precondition(Set(CapturePolicy.sensitiveMarkers) == Set(markers))
        precondition(CapturePolicy.sensitiveMarkers.count == 6)
        precondition(CapturePolicy.defaultExcludedAppBundleIDs == ["com.apple.keychainaccess", "com.apple.Passwords"])
        let bundleIDs: [String?] = [nil, "org.example.editor", "com.apple.keychainaccess", "com.apple.Passwords"]
        let markerCases: [String?] = [nil] + markers.map { Optional($0) }
        // Full matrix: disabling the marker filter must never disable app exclusion or pause.
        for paused in [false, true] {
            for ignore in [false, true] {
                for bundleID in bundleIDs {
                    for marker in markerCases {
                        let types = ["public.utf8-plain-text"] + (marker.map { [$0] } ?? [])
                        let excluded = bundleID == "com.apple.keychainaccess" || bundleID == "com.apple.Passwords"
                        let expected = !paused && !excluded && !(ignore && marker != nil)
                        precondition(CapturePolicy.shouldSave(types: types, sourceBundleID: bundleID,
                            excludedAppBundleIDs: CapturePolicy.defaultExcludedAppBundleIDs,
                            isPaused: paused, ignoreConcealed: ignore) == expected,
                            "pause=\(paused), ignore=\(ignore), app=\(String(describing: bundleID)), marker=\(String(describing: marker))")
                    }
                }
            }
        }
        precondition(!CapturePolicy.shouldSave(types: [], sourceBundleID: "org.example.custom",
            excludedAppBundleIDs: ["org.example.custom"], isPaused: false, ignoreConcealed: false))
        precondition(CapturePolicy.shouldSave(types: [], sourceBundleID: "com.apple.Passwords",
            excludedAppBundleIDs: [], isPaused: false, ignoreConcealed: true))
        precondition(CapturePolicy.shouldSave(types: ["org.nspasteboard.ConcealedType.extra"], sourceBundleID: nil,
            excludedAppBundleIDs: [], isPaused: false, ignoreConcealed: true))
        precondition(!CapturePolicy.shouldSave(types: markers, sourceBundleID: nil,
            excludedAppBundleIDs: [], isPaused: false, ignoreConcealed: true))
        precondition(CapturePolicy.shouldSave(types: markers, sourceBundleID: nil,
            excludedAppBundleIDs: [], isPaused: false, ignoreConcealed: false))
    }
}
